solutions.naive:
class Solution:
    def countAndSay(self, n: int) -> str:
        term = "1"
        for _ in range(n - 1):
            next_term = ""
            while term:
                digit = term[0]
                count = 0
                while count < len(term) and term[count] == digit:
                    count += 1
                next_term += str(count) + digit
                term = term[count:]  # Slicing repeatedly copies data.
            term = next_term
        return term

solutions.better:
class Solution:
    def countAndSay(self, n: int) -> str:
        term = "1"
        for _ in range(n - 1):
            pieces = []
            i = 0
            while i < len(term):
                j = i
                while j < len(term) and term[j] == term[i]:
                    j += 1
                pieces.append(str(j - i))
                pieces.append(term[i])
                i = j
            term = ''.join(pieces)
        return term

